fn env_lock() -> &'static Mutex<()> {
    static LOCK: OnceLock<Mutex<()>> = OnceLock::new();
    LOCK.get_or_init(|| Mutex::new(()))
}

struct EnvVarGuard {
    key: &'static str,
    previous: Option<String>,
}

impl EnvVarGuard {
    fn set(key: &'static str, value: &str) -> Self {
        let previous = std::env::var(key).ok();
        unsafe {
            std::env::set_var(key, value);
        }
        Self { key, previous }
    }

    fn remove(key: &'static str) -> Self {
        let previous = std::env::var(key).ok();
        unsafe {
            std::env::remove_var(key);
        }
        Self { key, previous }
    }
}

impl Drop for EnvVarGuard {
    fn drop(&mut self) {
        unsafe {
            if let Some(previous) = self.previous.as_ref() {
                std::env::set_var(self.key, previous);
            } else {
                std::env::remove_var(self.key);
            }
        }
    }
}

#[test]
fn ontology_onboarding_demo_profiles_have_expected_tables_and_evidence() {
    let datasets = ontology_demo_datasets();
    let profiles = ontology_profile_demo_datasets(&datasets);
    let table_names = profiles
        .iter()
        .map(|profile| profile.table_name.as_str())
        .collect::<Vec<_>>();

    assert_eq!(profiles.len(), 8);
    assert!(table_names.contains(&"customers"));
    assert!(table_names.contains(&"orders"));
    assert!(table_names.contains(&"order_items"));

    let orders = profiles
        .iter()
        .find(|profile| profile.table_name == "orders")
        .expect("orders profile");
    assert_eq!(orders.row_count, 4);
    assert!(orders.primary_key_candidates.contains(&"id".to_string()));
    assert!(orders.foreign_key_candidates.iter().any(|candidate| {
        candidate.field == "customer_id"
            && candidate.references_table == "customers"
            && candidate.references_field == "id"
            && candidate.join_success_rate >= 0.99
    }));
    assert!(orders.currency_fields.contains(&"total_price".to_string()));
}

#[test]
fn ontology_onboarding_demo_generates_required_proposals() {
    let datasets = ontology_demo_datasets();
    let profiles = ontology_profile_demo_datasets(&datasets);
    let proposals = ontology_generate_demo_proposals(&datasets, &profiles);

    let object_count = proposals
        .iter()
        .filter(|proposal| proposal.proposal_type == "object")
        .count();
    let relation_count = proposals
        .iter()
        .filter(|proposal| proposal.proposal_type == "relation")
        .count();
    let metric_count = proposals
        .iter()
        .filter(|proposal| proposal.proposal_type == "metric")
        .count();
    let action_count = proposals
        .iter()
        .filter(|proposal| proposal.proposal_type == "action")
        .count();
    let logic_count = proposals
        .iter()
        .filter(|proposal| proposal.proposal_type == "logic")
        .count();

    assert!(object_count >= 8);
    assert!(relation_count >= 7);
    assert!(metric_count >= 5);
    assert!(action_count >= 4);
    assert!(logic_count >= 8);
    assert!(proposals.iter().all(|proposal| proposal.confidence >= 0.70));
    assert!(
        proposals
            .iter()
            .all(|proposal| proposal.evidence.is_object())
    );
    assert!(proposals.iter().any(|proposal| {
        proposal.proposal_type == "relation"
            && proposal.name == "Customer places Order"
            && proposal.evidence["join_success_rate"]
                .as_f64()
                .unwrap_or_default()
                >= 0.99
    }));
    assert!(proposals.iter().any(|proposal| {
        proposal.proposal_type == "action"
            && proposal.name == "refund_order"
            && proposal.content["policy"]["approval_required"].as_bool() == Some(true)
            && proposal.content["transaction_profile"].as_str() == Some("proposal_only")
            && proposal.content["transaction_policy"]["execution_mode"].as_str()
                == Some("proposal_only")
    }));
    assert!(proposals.iter().any(|proposal| {
        proposal.proposal_type == "logic"
            && proposal.name == "Customer identity rule"
            && proposal.content["enabled"].as_bool() == Some(false)
    }));
}

#[test]
fn ontology_builder_dag_validates_execution_levels_and_cycles() {
    let dag = ontology_builder_dag_for_mode("pipeline_mapping_v2", None, Some("raw_snapshot"))
        .expect("pipeline mapping dag");
    assert!(dag.execution_levels.iter().any(|level| {
        level.node_ids.contains(&"metadata_scan".to_string())
            && level.node_ids.contains(&"schema_profile".to_string())
    }));
    assert!(dag.stale_node_ids.contains(&"proposal_engine".to_string()));

    let nodes = vec![
        ontology_builder_node("a", "A", "test", "ready", "A"),
        ontology_builder_node("b", "B", "test", "ready", "B"),
    ];
    let edges = vec![
        ontology_builder_edge("a", "b", "depends_on", "A before B"),
        ontology_builder_edge("b", "a", "depends_on", "B before A"),
    ];
    assert!(ontology_topological_execution_levels(&nodes, &edges).is_err());
}

#[test]
fn ontology_builder_seed_pack_generates_non_ecommerce_proposals() {
    let source = ontology_insurance_demo_source_bundle();
    let seed = ontology_insurance_seed_pack();
    let profiles = ontology_profile_demo_datasets(&source.datasets);
    let proposals = ontology_generate_seed_proposals_for_run(
        Uuid::new_v4(),
        &seed,
        &source.datasets,
        &profiles,
    );

    assert!(proposals.iter().any(|proposal| {
        proposal.proposal_type == "object"
            && proposal.name == "Policy"
            && proposal.content["domain_scope"].as_str() == Some("insurance")
    }));
    assert!(proposals.iter().any(|proposal| {
        proposal.proposal_type == "relation"
            && proposal.name == "Insured files Claim"
            && proposal.evidence["join_success_rate"]
                .as_f64()
                .unwrap_or_default()
                >= 0.99
    }));
    assert!(
        proposals.iter().any(|proposal| {
            proposal.proposal_type == "metric" && proposal.name == "Loss Ratio"
        })
    );
    assert!(proposals.iter().any(|proposal| {
        proposal.proposal_type == "action"
            && proposal.name == "approve_claim"
            && proposal.content["tool_namespace"].as_str() == Some("insurance")
            && proposal.content["audit_event"].as_str() == Some("insurance.approve_claim")
    }));
    assert!(proposals.iter().any(|proposal| {
        proposal.proposal_type == "logic"
            && proposal.name == "Policy identity rule"
            && proposal.content["source_mode"].as_str() == Some("demo_insurance")
    }));
}

#[test]
fn ontology_intelligence_schema_understanding_maps_ecommerce_orders() {
    let source = ontology_demo_source_bundle();
    let seed = ontology_ecommerce_seed_pack();
    let profiles = ontology_profile_demo_datasets(&source.datasets);
    let response =
        ontology_schema_understanding_for_datasets(None, &seed, &source.datasets, &profiles, 5);

    assert_eq!(response.industry, "ecommerce");
    assert_eq!(response.source_mode, "demo_ecommerce");
    assert_eq!(response.candidate_count, 8);
    let orders = response
        .candidates
        .iter()
        .find(|candidate| candidate.table_name == "orders")
        .expect("orders candidate");
    assert_eq!(orders.object_type_candidate, "Order");
    assert!(orders.confidence >= 0.90);
    assert_eq!(orders.recommendation, "draft_ready");
    assert_eq!(
        orders.evidence["seed_ontology_match"].as_str(),
        Some("Order")
    );
    assert!(
        orders
            .properties
            .iter()
            .any(|property| property.field_name == "id" && property.semantic_role == "primary_key")
    );
    assert!(orders.properties.iter().any(|property| {
        property.field_name == "customer_id" && property.semantic_role == "foreign_key"
    }));
    assert!(
        orders
            .taxonomy_layers
            .iter()
            .any(|layer| { layer.layer == 2 && layer.label == "Commerce" })
    );
}

