#[test]
fn ontology_intelligence_schema_understanding_marks_low_evidence_for_review() {
    let dataset = ontology_demo_dataset(
        "mystery_events",
        "demo_unknown",
        "mystery_events",
        vec![("payload", "string"), ("note", "string")],
        vec![
            json!({"payload":"opaque","note":null}),
            json!({"payload":"opaque","note":null}),
        ],
    );
    let datasets = vec![dataset];
    let profiles = ontology_profile_demo_datasets(&datasets);
    let seed = OntologySeedPack {
        industry: "unknown".to_string(),
        domain_scope: "unknown".to_string(),
        source_mode: "demo_unknown".to_string(),
        tool_namespace: "unknown".to_string(),
        objects: Vec::new(),
        relations: Vec::new(),
        metrics: Vec::new(),
        actions: Vec::new(),
    };
    let response = ontology_schema_understanding_for_datasets(None, &seed, &datasets, &profiles, 5);
    let candidate = response.candidates.first().expect("candidate");

    assert_eq!(candidate.object_type_candidate, "MysteryEvent");
    assert!(candidate.confidence < 0.70);
    assert_eq!(candidate.recommendation, "needs_review");
    assert!(candidate.evidence["seed_ontology_match"].is_null());
    assert!(
        candidate
            .taxonomy_layers
            .iter()
            .any(|layer| { layer.layer == 3 && layer.rationale.contains("requires human review") })
    );
}

#[tokio::test]
async fn ontology_intelligence_order_subgraph_contains_business_context() {
    let state = test_state_with_worker(Arc::new(InlineExecutionWorker));
    let run = create_demo_ontology_onboarding_run_for_test(&state)
        .await
        .expect("demo run");
    let response = ontology_subgraph_proposals_for_request(
        &state,
        &SubgraphProposalRequest {
            run_id: Some(run.id),
            industry: None,
            source_mode: None,
            target_object: Some("Order".to_string()),
            review_decision: None,
        },
    )
    .await
    .expect("subgraph proposals");

    assert_eq!(response.run_id, Some(run.id));
    assert_eq!(response.subgraph_count, 1);
    let order_subgraph = response.subgraphs.first().expect("order subgraph");
    let member_names = order_subgraph
        .members
        .iter()
        .map(|member| member.name.as_str())
        .collect::<BTreeSet<_>>();

    assert!(member_names.contains("Customer"));
    assert!(member_names.contains("Order"));
    assert!(member_names.contains("OrderLine"));
    assert!(member_names.contains("SKU"));
    assert!(member_names.contains("Customer places Order"));
    assert!(member_names.contains("Order contains OrderLine"));
    assert!(member_names.contains("GMV"));
    assert!(member_names.contains("refund_order"));
    assert!(
        order_subgraph
            .members
            .iter()
            .all(|member| member.proposal_id != Uuid::nil())
    );
    assert_eq!(
        order_subgraph.evidence["authority"].as_str(),
        Some("proposal_only")
    );
}

