#[test]
fn stage2_readiness_evidence_metadata_matches_repo_contract() {
    let root = repo_root();
    let readiness = build_stage2_completion_readiness();
    let production_gate = read_repo_file(&root, "scripts/stage2-production-evidence-gate.sh");
    let completion_audit = read_repo_file(&root, "scripts/stage2-completion-audit-gate.sh");
    assert!(
        production_gate.contains("INCLUDE_ENTERPRISE_OPTIONAL"),
        "production evidence gate must keep enterprise plugin evidence opt-in"
    );
    assert!(
        production_gate.contains("required_for_stage2_production"),
        "production evidence gate must filter declared endpoint coverage to Stage 2 production requirements by default"
    );
    assert!(
        completion_audit.contains("required_for_stage2_production"),
        "completion audit gate must classify optional enterprise evidence separately from Stage 2 production requirements"
    );
    assert!(
        completion_audit.contains("optional_missing_required_evidence_artifact_count"),
        "completion audit gate must report optional enterprise evidence without making it a core blocker"
    );
    assert!(
        completion_audit.contains("stage2-production-evidence-preflight.json")
            && completion_audit
                .contains("strict Stage 2 production evidence preflight summary is incomplete"),
        "completion audit gate must require strict Stage 2 production evidence preflight success before archive verification"
    );
    let controller_env = read_repo_file(
        &root,
        "deploy/stage2-evidence/stage2-production-controllers.env.example",
    );
    let controller_secret = read_repo_file(
        &root,
        "deploy/stage2-evidence/stage2-controller-env-secret.example.yaml",
    );

    for requirement in &readiness.evidence_requirements {
        assert!(
            !requirement.evidence_scripts.is_empty(),
            "{} must declare evidence scripts",
            requirement.id
        );
        assert!(
            !requirement.evidence_job_manifests.is_empty(),
            "{} must declare evidence Job manifests",
            requirement.id
        );
        assert!(
            !requirement.required_artifacts.is_empty(),
            "{} must declare required evidence artifacts",
            requirement.id
        );

        let mut focused_sources = String::new();
        for script in &requirement.evidence_scripts {
            let script_path = repo_path(&root, script);
            assert!(
                script_path.is_file(),
                "{} declares missing evidence script {}",
                requirement.id,
                script
            );
            assert_executable(&script_path, script);
            focused_sources.push_str(&read_repo_file(&root, script));
            focused_sources.push('\n');
        }

        for manifest in &requirement.evidence_job_manifests {
            let manifest_path = repo_path(&root, manifest);
            assert!(
                manifest_path.is_file(),
                "{} declares missing evidence Job manifest {}",
                requirement.id,
                manifest
            );
            let manifest_source = read_repo_file(&root, manifest);
            assert!(
                manifest_source.contains("claimName: mandoforge-stage2-production-evidence"),
                "{} manifest {} must persist evidence to the production PVC",
                requirement.id,
                manifest
            );
        }

        for required_flag in &requirement.required_flags {
            let flag_name = required_flag
                .split_once('=')
                .map_or(required_flag.as_str(), |(name, _)| name);
            assert!(
                controller_env.contains(&format!("{flag_name}=")),
                "{} required flag {} is missing from controller env example",
                requirement.id,
                flag_name
            );
            assert!(
                controller_secret.contains(&format!("{flag_name}:")),
                "{} required flag {} is missing from controller Secret example",
                requirement.id,
                flag_name
            );
        }

        let endpoint_artifacts = requirement
            .readiness_endpoints
            .iter()
            .chain(requirement.validation_endpoints.iter())
            .filter(|endpoint| !endpoint.starts_with("./"))
            .map(|endpoint| format!("{}.json", slugify_for_stage2_evidence(endpoint)))
            .collect::<Vec<_>>();
        let local_script_artifacts = requirement
            .evidence_scripts
            .iter()
            .map(|script| {
                format!(
                    "local-script-{}.json",
                    slugify_for_stage2_evidence(script.trim_start_matches("./"))
                )
            })
            .collect::<Vec<_>>();

        for artifact in &requirement.required_artifacts {
            let has_literal_writer = focused_sources.contains(artifact)
                || production_gate.contains(artifact)
                || completion_audit.contains(artifact);
            let has_endpoint_writer = endpoint_artifacts
                .iter()
                .any(|candidate| candidate == artifact);
            let has_local_script_writer = local_script_artifacts
                .iter()
                .any(|candidate| candidate == artifact);
            assert!(
                has_literal_writer || has_endpoint_writer || has_local_script_writer,
                "{} required artifact {} is not backed by a focused script, strict gate endpoint capture, or local-script capture",
                requirement.id,
                artifact
            );
        }
    }
}

fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .and_then(Path::parent)
        .expect("api crate must live under crates/mandoforge-api")
        .to_path_buf()
}

fn repo_path(root: &Path, relative: &str) -> PathBuf {
    root.join(relative.trim_start_matches("./"))
}

fn read_repo_file(root: &Path, relative: &str) -> String {
    let path = repo_path(root, relative);
    fs::read_to_string(&path)
        .unwrap_or_else(|error| panic!("failed to read {}: {error}", path.display()))
}

#[cfg(unix)]
fn assert_executable(path: &Path, label: &str) {
    let mode = fs::metadata(path)
        .unwrap_or_else(|error| panic!("failed to stat {}: {error}", path.display()))
        .permissions()
        .mode();
    assert!(
        mode & 0o111 != 0,
        "evidence script {label} must be executable"
    );
}

#[cfg(not(unix))]
fn assert_executable(path: &Path, _label: &str) {
    assert!(path.is_file());
}

fn slugify_for_stage2_evidence(value: &str) -> String {
    let mut output = String::new();
    let mut previous_separator = false;
    for ch in value.trim_start_matches('/').chars() {
        if ch == '/' || ch == ':' {
            if !previous_separator {
                output.push('-');
                previous_separator = true;
            }
        } else if ch.is_ascii_alphanumeric() || ch == '.' || ch == '_' || ch == '-' {
            output.push(ch);
            previous_separator = false;
        } else {
            if !previous_separator {
                output.push('-');
                previous_separator = true;
            }
        }
    }
    output
}

#[test]
fn registry_contains_allowed_stage1_tools() {
    let registry = tool_registry();
    for expected in [
        "artifact.create",
        "approval.request",
        "file.read",
        "ontology_type.lookup",
        "semantic_link.expand",
        "semantic_object.fetch",
        "sql.get_schema",
        "sql.query",
    ] {
        assert!(registry.contains_key(expected), "missing {expected}");
    }

    let descriptors = tool_descriptors();
    for expected in ["file.write", "shell.exec", "codex.exec"] {
        assert!(
            descriptors
                .iter()
                .any(|descriptor| descriptor.name == expected),
            "missing descriptor {expected}"
        );
    }
}

#[test]
fn wraps_read_only_sql_for_json_with_row_limit() {
    let wrapped =
        wrap_read_only_sql_for_json("select event_type from generic_demo.platform_events;", 25);
    assert!(wrapped.contains("jsonb_agg"));
    assert!(wrapped.contains("LIMIT 25"));
    assert!(wrapped.contains("select event_type from generic_demo.platform_events"));
    assert!(!wrapped.contains("platform_events;"));
}

#[test]
fn parses_codex_jsonl_events_and_ignores_non_json_lines() {
    let events = parse_codex_jsonl(
        r#"{"type":"session.started","id":"a"}
not json
{"msg":"agent.message","text":"done"}
"#,
    );
    assert_eq!(events.len(), 2);
    assert_eq!(codex_jsonl_event_type(&events[0]), "session.started");
    assert_eq!(codex_jsonl_event_type(&events[1]), "agent.message");
}

#[test]
fn builds_usage_trend_from_rollups_and_budget_pressure() {
    let generated_at = "2026-05-13T00:00:00Z"
        .parse::<DateTime<Utc>>()
        .expect("valid time");
    let current = UsageSummary {
        session_count: 1,
        event_count: 2,
        provider_request_count: 1,
        provider_response_count: 1,
        tool_call_count: 3,
        tool_success_count: 2,
        tool_failed_count: 1,
        approval_count: 1,
        prompt_tokens: 120,
        completion_tokens: 80,
        total_tokens: 200,
        total_tool_duration_ms: 1000,
        estimated_provider_cost_cents: 15.0,
        by_provider: HashMap::from([(
            "mock".to_string(),
            ProviderUsageSummary {
                request_count: 1,
                response_count: 1,
                prompt_tokens: 120,
                completion_tokens: 80,
                total_tokens: 200,
                token_cost_cents: 5.0,
                estimated_cost_cents: 15.0,
            },
        )]),
        by_tool: HashMap::new(),
        provider_budgets: vec![ProviderBudgetStatus {
            provider_name: "mock".to_string(),
            status: "warning".to_string(),
            window_hours: 24,
            request_count: 8,
            daily_request_limit: Some(10),
            request_budget_used_percent: Some(80.0),
            estimated_cost_cents: 15.0,
            projected_daily_cost_cents: 15.0,
            daily_cost_limit_cents: Some(20.0),
            cost_budget_used_percent: Some(75.0),
            messages: vec!["8 of 10 daily requests used (80.0%)".to_string()],
        }],
    };
    let rollups = vec![
        UsageRollup {
            id: Uuid::new_v4(),
            period_start: "2026-05-12T00:00:00Z".parse().expect("valid time"),
            period_end: "2026-05-13T00:00:00Z".parse().expect("valid time"),
            summary: json!({
                "estimated_provider_cost_cents": 15.0,
                "total_tokens": 200,
                "tool_call_count": 3
            }),
            created_at: generated_at,
        },
        UsageRollup {
            id: Uuid::new_v4(),
            period_start: "2026-05-11T00:00:00Z".parse().expect("valid time"),
            period_end: "2026-05-12T00:00:00Z".parse().expect("valid time"),
            summary: json!({
                "estimated_provider_cost_cents": 10.0,
                "total_tokens": 100,
                "tool_call_count": 2
            }),
            created_at: generated_at - chrono::Duration::hours(24),
        },
    ];
    let trend = build_usage_trend_from_parts(current, &rollups, generated_at);
    assert_eq!(trend.comparison_basis, "latest_rollups");
    assert_eq!(trend.rollup_count, 2);
    assert_eq!(trend.cost_delta_cents, Some(5.0));
    assert_eq!(trend.cost_delta_percent, Some(50.0));
    assert_eq!(trend.token_delta, Some(100));
    assert_eq!(trend.tool_call_delta, Some(1));
    assert_eq!(trend.top_provider_by_cost.unwrap().provider_name, "mock");
    assert_eq!(trend.budget_pressure.warning_count, 1);
    assert_eq!(trend.budget_pressure.highest_status, "warning");
    assert_eq!(trend.forecast.basis, "current_24h_run_rate");
    assert_eq!(trend.forecast.horizons.len(), 2);
    assert_eq!(trend.forecast.horizons[0].days, 7);
    assert_eq!(trend.forecast.horizons[0].projected_tokens, 1400);
    assert!((trend.forecast.horizons[0].projected_cost_cents - 105.0).abs() < 0.000001);
    let budget_forecast = trend
        .forecast
        .provider_budget_exhaustion
        .iter()
        .find(|forecast| forecast.provider_name == "mock")
        .expect("mock budget forecast");
    assert_eq!(budget_forecast.status, "warning");
    assert_eq!(budget_forecast.daily_cost_limit_cents, 20.0);
    assert_eq!(budget_forecast.projected_days_to_limit, Some(1.0 / 3.0));
    assert!(
        trend
            .recommendations
            .iter()
            .any(|recommendation| recommendation == "provider_budget_watch")
    );
    assert!(
        trend
            .recommendations
            .iter()
            .any(|recommendation| recommendation == "cost_growth_investigation")
    );
}

