#[tokio::test]
async fn agent_registry_state_tracks_configured_release_environment() {
    let _env = env_lock().lock().expect("env lock");
    let _release_environment =
        EnvVarGuard::set("MANDOFORGE_AGENT_RELEASE_ENVIRONMENT", "production");
    let state = test_state_with_worker(Arc::new(InlineExecutionWorker));
    let agent = state
        .create_agent(CreateAgent {
            name: "Release State Agent".to_string(),
            kind: "orchestrator".to_string(),
            provider: "openai-compatible".to_string(),
            model: "gpt-5.5-mini".to_string(),
            team_id: None,
            project_id: None,
            runtime_profile_id: None,
            agent_role: "specialist".to_string(),
            system_prompt: "Prove release state activation.".to_string(),
            runtime_config: json!({}),
            tools: vec!["file.read".to_string()],
            tool_policy: json!({}),
            mcp_server_ids: vec![],
            skill_ids: vec![],
            workflow_pack_ids: vec![],
            remote_computer_profile: json!({}),
            semantic_scopes: json!({}),
            release_state: "draft".to_string(),
        })
        .await
        .expect("create draft agent");
    let dataset = state
        .create_eval_dataset(CreateEvalDataset {
            name: "release state activation".to_string(),
            description: None,
        })
        .await
        .expect("create eval dataset");
    state
        .create_eval_case(
            dataset.id,
            CreateEvalCase {
                input: json!({"final_answer": "release ready"}),
                expected: Some(json!({"contains": ["release"]})),
                grading_policy: json!({"kind": "final_answer"}),
            },
        )
        .await
        .expect("create eval case");
    let run = state
        .create_eval_run(dataset.id, CreateEvalRun { agent_id: agent.id })
        .await
        .expect("create eval run");
    assert_eq!(run.status, "completed");

    state
        .create_agent_release(
            agent.id,
            CreateAgentRelease {
                agent_version_id: None,
                eval_run_id: run.id,
                environment: "staging".to_string(),
                min_score: Some(1.0),
            },
            "release-admin".to_string(),
        )
        .await
        .expect("promote staging agent release");

    assert_eq!(
        state
            .get_agent(agent.id)
            .await
            .expect("staging agent")
            .release_state,
        "staged"
    );

    let version = state
        .current_agent_version(agent.id)
        .await
        .expect("agent version");
    let automated_release = crate::store_releases::new_workflow_pack_agent_release(
        Uuid::new_v4(),
        agent.id,
        version.id,
        "production",
        "workflow-pack-release",
        &json!({"release_gate_id": "automated-before-independent-promotion"}),
        Utc::now(),
    );
    let StoreBackend::Memory(inner) = &state.store else {
        panic!("test requires memory store");
    };
    inner
        .write()
        .await
        .agent_releases
        .insert(automated_release.id, automated_release.clone());

    let production_release = state
        .create_agent_release(
            agent.id,
            CreateAgentRelease {
                agent_version_id: None,
                eval_run_id: run.id,
                environment: "production".to_string(),
                min_score: Some(1.0),
            },
            "release-admin".to_string(),
        )
        .await
        .expect("promote production agent release");
    assert_ne!(production_release.id, automated_release.id);
    assert_eq!(
        state
            .list_all_agent_releases()
            .await
            .expect("list releases")
            .into_iter()
            .find(|release| release.id == automated_release.id)
            .expect("automated release")
            .status,
        "superseded"
    );

    assert_eq!(
        state
            .get_agent(agent.id)
            .await
            .expect("released agent")
            .release_state,
        "active"
    );

    state
        .rollback_agent_release(agent.id, production_release.id)
        .await
        .expect("rollback production release");
    assert_eq!(
        state
            .get_agent(agent.id)
            .await
            .expect("rolled back agent")
            .release_state,
        "staged"
    );
}

#[tokio::test]
async fn sessions_bind_agent_version_and_enforce_tool_allowlist() {
    let app = test_app().await;
    let created: Agent = request_json(
        app.clone(),
        Request::builder()
            .method("POST")
            .uri("/api/agents")
            .header("content-type", "application/json")
            .header("x-mandoforge-roles", "admin")
            .body(Body::from(
                json!({
                "name": "Read Only Agent",
                "kind": "orchestrator",
                "provider": "openai-compatible",
                "model": "gpt-5.5-mini",
                "system_prompt": "Read only.",
                "tools": ["file.read"]
                })
                .to_string(),
            ))
            .expect("valid request"),
    )
    .await;
    let versions: Vec<AgentVersion> = request_json(
        app.clone(),
        Request::builder()
            .uri(format!("/api/agents/{}/versions", created.id))
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    let version = versions.first().expect("agent version");
    let session: Session = request_json(
        app.clone(),
        json_request(
            "POST",
            "/api/sessions",
            json!({"agent_id": created.id, "title": "version policy"}),
        ),
    )
    .await;
    assert_eq!(session.agent_version_id, Some(version.id));

    let (status, error) = request_value(
        app.clone(),
        json_request(
            "POST",
            "/api/tools/sql.get_schema/execute",
            json!({"session_id": session.id, "args": {}}),
        ),
    )
    .await;
    assert_eq!(status, StatusCode::FORBIDDEN);
    assert_eq!(
        error["error"].as_str(),
        Some("sql.get_schema is not enabled for agent version 1")
    );

    let tool_calls: Vec<ToolCall> = request_json(
        app,
        Request::builder()
            .uri(format!("/api/sessions/{}/tool-calls", session.id))
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    assert!(tool_calls.iter().any(|call| {
        call.tool_name == "sql.get_schema"
            && call.status == "denied"
            && call.policy_decision["decision"] == "denied"
            && call.policy_decision["agent_version_id"] == json!(version.id)
    }));
}

