#[tokio::test]
async fn workflow_pack_supersede_does_not_rewrite_historical_records() {
    let state = test_state_with_worker(Arc::new(InlineExecutionWorker));
    let installation_id = Uuid::new_v4();
    let binding_id = Uuid::new_v4();
    let runtime_object_id = Uuid::new_v4();
    let first_at = Utc::now() - chrono::Duration::minutes(3);
    let second_at = Utc::now() - chrono::Duration::minutes(2);
    let third_at = Utc::now() - chrono::Duration::minutes(1);

    let binding = |id, key: &str, timestamp| WorkflowPackBinding {
        id,
        installation_id,
        pack_id: "ecommerce-test".to_string(),
        pack_version: "0.1.0".to_string(),
        binding_type: "workflow".to_string(),
        binding_key: key.to_string(),
        source_path: Some(format!("workflows/{key}.yaml")),
        target_kind: "workflow_definition".to_string(),
        target_id: None,
        status: "staged".to_string(),
        materialized_payload: json!({"key": key}),
        created_at: timestamp,
        updated_at: timestamp,
    };
    let runtime_object = |id, key: &str, timestamp| WorkflowPackRuntimeObject {
        id,
        installation_id,
        binding_id: Uuid::new_v4(),
        pack_id: "ecommerce-test".to_string(),
        pack_version: "0.1.0".to_string(),
        object_type: "schedule".to_string(),
        object_key: key.to_string(),
        runtime_kind: "semantic_synthesis_schedule".to_string(),
        status: "staged".to_string(),
        spec: json!({"key": key}),
        created_at: timestamp,
        updated_at: timestamp,
    };

    state
        .create_workflow_pack_bindings(vec![binding(binding_id, "first", first_at)])
        .await
        .expect("first binding");
    state
        .create_workflow_pack_runtime_objects(vec![runtime_object(
            runtime_object_id,
            "first",
            first_at,
        )])
        .await
        .expect("first runtime object");
    state
        .create_workflow_pack_bindings(vec![binding(Uuid::new_v4(), "second", second_at)])
        .await
        .expect("second binding");
    state
        .create_workflow_pack_runtime_objects(vec![runtime_object(
            Uuid::new_v4(),
            "second",
            second_at,
        )])
        .await
        .expect("second runtime object");

    let (binding_superseded_at, runtime_object_superseded_at) = match &state.store {
        StoreBackend::Memory(inner) => {
            let store = inner.read().await;
            (
                store.workflow_pack_bindings[&binding_id].updated_at,
                store.workflow_pack_runtime_objects[&runtime_object_id].updated_at,
            )
        }
        StoreBackend::Postgres(_) => unreachable!("test uses memory store"),
    };

    state
        .create_workflow_pack_bindings(vec![binding(Uuid::new_v4(), "third", third_at)])
        .await
        .expect("third binding");
    state
        .create_workflow_pack_runtime_objects(vec![runtime_object(
            Uuid::new_v4(),
            "third",
            third_at,
        )])
        .await
        .expect("third runtime object");

    match &state.store {
        StoreBackend::Memory(inner) => {
            let store = inner.read().await;
            let historical_binding = &store.workflow_pack_bindings[&binding_id];
            let historical_runtime_object =
                &store.workflow_pack_runtime_objects[&runtime_object_id];
            assert_eq!(historical_binding.status, "superseded");
            assert_eq!(historical_runtime_object.status, "superseded");
            assert_eq!(historical_binding.updated_at, binding_superseded_at);
            assert_eq!(
                historical_runtime_object.updated_at,
                runtime_object_superseded_at
            );
        }
        StoreBackend::Postgres(_) => unreachable!("test uses memory store"),
    }
}

