            && object.object_key
                == format!(
                    "workflow_pack:{}:workflow:customer-service-conversation",
                    installed.id
                )
            && object.semantic_scopes["domain_scope"] == json!("ecommerce")
            && object.semantic_scopes["lane_scope"] == json!("customer-service")
