#[test]
fn dynamic_workflow_native_dynamic_graph_models_evaluator_feedback_loop() {
    let now = Utc::now();
    let plan = DynamicWorkflowPlan {
        id: Uuid::new_v4(),
        source_work_item_id: None,
        source_session_id: None,
        objective: "Implement a milestone and verify it with external evaluators".to_string(),
        status: "approved".to_string(),
        phases: json!([
            {
                "key": "implementation",
                "prompt": "Implement the requested milestone."
            }
        ]),
        agent_fleet_policy: json!({
            "max_total_agents": 12,
            "max_parallel_agents": 4
        }),
        governance: default_dynamic_workflow_governance(),
        validation: default_dynamic_workflow_validation(),
        materialization: json!({
            "execution_strategy": "native_dynamic",
            "runtime_adapter": "codex_app_server",
            "runtime_mode": "dynamic_workflow"
        }),
        analysis: empty_json_object(),
        review: empty_json_object(),
        workflow_definition_id: None,
        workflow_run_id: None,
        audit_trace_id: None,
        created_at: now,
        updated_at: now,
        reviewed_at: None,
        materialized_at: None,
    };

    let graph = dynamic_workflow_plan_step_graph(&plan, "native_dynamic")
        .expect("native dynamic graph is generated");
    let steps = graph["steps"].as_array().expect("steps");
    let keys = steps
        .iter()
        .map(|step| step["key"].as_str().expect("step key"))
        .collect::<Vec<_>>();
    assert_eq!(
        keys,
        vec![
            "implement",
            "implementation-evaluator",
            "developer",
            "troubleshooter",
            "integration-tester",
            "integration-gate-keeper",
            "unexpected-error"
        ]
    );
    assert_eq!(steps[0]["start"], json!(true));
    assert_eq!(steps[1]["depends_on"], json!(["implement"]));
    assert_eq!(
        steps[2]["condition"]["path"],
        json!("/evaluation/found_gap")
    );
    assert_eq!(
        steps[3]["condition"]["path"],
        json!("/evaluation/found_issues")
    );
    assert_eq!(steps[5]["condition"]["path"], json!("/integration/no_gap"));
    assert_eq!(
        steps[6]["on_failure_of"],
        json!([
            "implement",
            "developer",
            "troubleshooter",
            "integration-tester"
        ])
    );
    assert_eq!(
        graph["dynamic_loop"]["terminal_success_step"],
        json!("integration-gate-keeper")
    );
}

#[tokio::test]
async fn workflow_definition_patch_rejects_invalid_graph_without_updating() {
    let app = test_app().await;
    let agents: Vec<Agent> = request_json(
        app.clone(),
        Request::builder()
            .uri("/api/agents")
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    let agent = agents.first().expect("seeded agent");

    let definition: Value = request_json(
        app.clone(),
        json_request_with_headers(
            "POST",
            "/api/workflow-definitions",
            json!({
                "name": "Editable graph workflow",
                "entrypoint": "editable-graph-workflow",
                "trigger_type": "manual",
                "default_agent_id": agent.id,
                "step_graph": {
                    "steps": [
                        {"key": "intake", "type": "agent", "start": true}
                    ]
                },
                "release_state": "draft"
            }),
            &[("x-mandoforge-roles", "admin")],
        ),
    )
    .await;
    let definition_id = definition["id"].as_str().expect("definition id");

    let (status, error) = request_value(
        app.clone(),
        json_request_with_headers(
            "PATCH",
            &format!("/api/workflow-definitions/{definition_id}"),
            json!({
                "step_graph": {
                    "steps": [
                        {"key": "intake", "type": "agent", "start": true},
                        {"key": "draft", "type": "agent", "depends_on": ["missing-step"]}
                    ]
                }
            }),
            &[("x-mandoforge-roles", "admin")],
        ),
    )
    .await;
    assert_eq!(status, StatusCode::BAD_REQUEST);
    assert!(
        error["error"]
            .as_str()
            .is_some_and(|message| message.contains("unknown step missing-step"))
    );

    let unchanged: Value = request_json(
        app,
        Request::builder()
            .uri(format!("/api/workflow-definitions/{definition_id}"))
            .header("x-mandoforge-roles", "admin")
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    assert_eq!(unchanged["name"], json!("Editable graph workflow"));
    assert_eq!(
        unchanged["step_graph"]["steps"]
            .as_array()
            .expect("steps")
            .len(),
        1
    );
}

#[tokio::test]
async fn workflow_definition_patch_updates_graph_and_records_audit() {
    let app = test_app().await;
    let agents: Vec<Agent> = request_json(
        app.clone(),
        Request::builder()
            .uri("/api/agents")
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    let agent = agents.first().expect("seeded agent");

    let definition: Value = request_json(
        app.clone(),
        json_request_with_headers(
            "POST",
            "/api/workflow-definitions",
            json!({
                "name": "Patchable graph workflow",
                "entrypoint": "patchable-graph-workflow",
                "trigger_type": "manual",
                "default_agent_id": agent.id,
                "step_graph": {
                    "steps": [
                        {"key": "intake", "type": "agent", "start": true}
                    ]
                },
                "handoff_rules": {"mode": "initial"},
                "release_state": "draft"
            }),
            &[("x-mandoforge-roles", "admin")],
        ),
    )
    .await;
    let definition_id = definition["id"].as_str().expect("definition id");
    let created_at = definition["created_at"].clone();

    let updated: Value = request_json(
        app.clone(),
        json_request_with_headers(
            "PATCH",
            &format!("/api/workflow-definitions/{definition_id}"),
            json!({
                "name": "Patched graph workflow",
                "step_graph": {
                    "steps": [
                        {"key": "intake", "type": "agent", "start": true},
                        {"key": "draft", "type": "agent", "depends_on": ["intake"]}
                    ]
                }
            }),
            &[("x-mandoforge-roles", "admin")],
        ),
    )
    .await;
    assert_eq!(updated["name"], json!("Patched graph workflow"));
    assert_eq!(updated["entrypoint"], json!("patchable-graph-workflow"));
    assert_eq!(updated["handoff_rules"], json!({"mode": "initial"}));
    assert_eq!(
        updated["step_graph"]["steps"]
            .as_array()
            .expect("steps")
            .len(),
        2
    );
    assert_eq!(updated["created_at"], created_at);
    assert_ne!(updated["updated_at"], definition["updated_at"]);

    let audit_logs: Vec<AuditLog> = request_json(
        app,
        Request::builder()
            .uri("/api/audit-logs")
            .header("x-mandoforge-roles", "admin")
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    assert!(audit_logs.iter().any(|log| {
        log.action == "workflow_definition.updated"
            && log.resource_id.map(|id| id.to_string()).as_deref() == Some(definition_id)
            && log.details["changed_fields"]
                .as_array()
                .is_some_and(|fields| fields.contains(&json!("step_graph")))
    }));
}

#[tokio::test]
async fn workflow_runs_create_primary_session_and_step_runs() {
    let app = test_app().await;
    let agents: Vec<Agent> = request_json(
        app.clone(),
        Request::builder()
            .uri("/api/agents")
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    let agent = agents.first().expect("seeded agent");

    let definition: Value = request_json(
        app.clone(),
        json_request_with_headers(
            "POST",
            "/api/workflow-definitions",
            json!({
                "name": "AI use case triage",
                "entrypoint": "ai-use-case-triage",
                "trigger_type": "manual",
                "default_agent_id": agent.id,
                "step_graph": {
                    "steps": [
                        {"key": "intake", "agent_role": "orchestrator"},
                        {"key": "draft", "agent_role": "writer"}
                    ]
                },
                "handoff_rules": {},
                "eval_gate_refs": ["pack-regression"],
                "release_state": "released"
            }),
            &[("x-mandoforge-roles", "admin")],
        ),
    )
    .await;
    assert_eq!(definition["name"], json!("AI use case triage"));
    assert_eq!(definition["default_agent_id"], json!(agent.id));

    let run: Value = request_json(
        app.clone(),
        json_request_with_headers(
            "POST",
            "/api/workflow-runs",
            json!({
                "workflow_definition_id": definition["id"],
                "title": "triage first AI use case",
                "input_payload": {
                    "use_case_id": "AI-001",
                    "owner": "legal"
                }
            }),
            &[("x-mandoforge-roles", "operator")],
        ),
    )
    .await;
    assert_eq!(run["workflow_definition_id"], definition["id"]);
    assert_eq!(run["status"], json!("queued"));
    assert!(run["primary_session_id"].as_str().is_some());
    assert!(run["root_task_grant_id"].as_str().is_some());
    assert!(run["input_digest"].as_str().is_some_and(|digest| {
        digest.starts_with("fnv1a64:") && digest.len() == "fnv1a64:0000000000000000".len()
    }));

    let session_id = run["primary_session_id"].as_str().expect("session id");
    let root_task_grant_id = run["root_task_grant_id"]
        .as_str()
        .expect("root task grant id");
    let events: Vec<SessionEvent> = request_json(
        app.clone(),
        Request::builder()
            .uri(format!("/api/sessions/{session_id}/events"))
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    assert!(events.iter().any(|event| {
        event.event_type == "workflow.run.created"
            && event.payload["workflow_run_id"] == run["id"]
            && event.payload["workflow_definition_id"] == definition["id"]
    }));
    assert!(events.iter().any(|event| {
        event.event_type == "task_grant.issued"
            && event.payload["task_grant_id"] == json!(root_task_grant_id)
            && event.payload["workflow_run_id"] == run["id"]
    }));

    let initial_steps: Vec<Value> = request_json(
        app.clone(),
        Request::builder()
            .uri(format!(
                "/api/workflow-runs/{}/steps",
                run["id"].as_str().unwrap()
            ))
            .header("x-mandoforge-roles", "operator")
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    assert_eq!(initial_steps.len(), 1);
    assert_eq!(initial_steps[0]["step_key"], json!("intake"));
    assert_eq!(initial_steps[0]["session_id"], json!(session_id));
    assert_eq!(initial_steps[0]["task_grant_id"], json!(root_task_grant_id));

    let grants: Vec<Value> = request_json(
        app.clone(),
        Request::builder()
            .uri(format!(
                "/api/workflow-runs/{}/task-grants",
                run["id"].as_str().unwrap()
            ))
            .header("x-mandoforge-roles", "operator")
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    assert_eq!(grants.len(), 1);
    assert_eq!(grants[0]["id"], json!(root_task_grant_id));
    assert_eq!(grants[0]["parent_grant_id"], Value::Null);
    assert_eq!(grants[0]["status"], json!("active"));
    assert_eq!(grants[0]["memory_scope"]["mode"], json!("snapshot_only"));

    let step: Value = request_json(
        app.clone(),
        json_request_with_headers(
            "POST",
            &format!("/api/workflow-runs/{}/steps", run["id"].as_str().unwrap()),
            json!({
                "step_key": "draft",
                "step_type": "agent",
                "agent_id": agent.id,
                "session_id": session_id,
                "task_grant_id": root_task_grant_id,
                "status": "queued",
                "input_payload": {"source": "workflow run test"}
            }),
            &[("x-mandoforge-roles", "operator")],
        ),
    )
    .await;
    assert_eq!(step["workflow_run_id"], run["id"]);
    assert_eq!(step["step_key"], json!("draft"));
    assert_eq!(step["session_id"], json!(session_id));
    assert_eq!(step["task_grant_id"], json!(root_task_grant_id));

    let (status, error) = request_value(
        app.clone(),
        json_request_with_headers(
            "POST",
            &format!("/api/workflow-runs/{}/steps", run["id"].as_str().unwrap()),
            json!({
                "step_key": "draft",
                "step_type": "agent",
                "agent_id": agent.id,
                "session_id": session_id,
                "task_grant_id": root_task_grant_id,
                "status": "queued"
            }),
            &[("x-mandoforge-roles", "operator")],
        ),
    )
    .await;
    assert_eq!(status, StatusCode::CONFLICT);
    assert_eq!(
        error["error"].as_str(),
        Some("workflow step key already exists for this workflow run")
    );

    let listed_steps: Vec<Value> = request_json(
        app.clone(),
        Request::builder()
            .uri(format!(
                "/api/workflow-runs/{}/steps",
                run["id"].as_str().unwrap()
            ))
            .header("x-mandoforge-roles", "operator")
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    assert_eq!(listed_steps.len(), 2);
    assert!(listed_steps.iter().any(|listed| listed["id"] == step["id"]));
    assert!(
        listed_steps
            .iter()
            .any(|listed| listed["id"] == initial_steps[0]["id"])
    );

    let listed_runs: Vec<Value> = request_json(
        app,
        Request::builder()
            .uri("/api/workflow-runs")
            .header("x-mandoforge-roles", "operator")
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    assert!(listed_runs.iter().any(|listed| listed["id"] == run["id"]));
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn workflow_step_key_reservation_is_atomic() {
    let state = test_state_with_worker(Arc::new(InlineExecutionWorker));
    let workflow_run_id = Uuid::new_v4();
    let caller_count = 32;
    let start = Arc::new(tokio::sync::Barrier::new(caller_count));
    let mut callers = Vec::with_capacity(caller_count);

    for _ in 0..caller_count {
        let caller_state = state.clone();
        let start = start.clone();
        callers.push(tokio::spawn(async move {
            start.wait().await;
            let now = Utc::now();
            caller_state
                .create_workflow_step_run_if_key_absent(WorkflowStepRun {
                    id: Uuid::new_v4(),
                    workflow_run_id,
                    step_key: "external-review".to_string(),
                    step_type: "agent".to_string(),
                    agent_id: None,
                    agent_version_id: None,
                    session_id: None,
                    thread_id: None,
                    handoff_id: None,
                    task_grant_id: None,
                    environment_id: None,
                    status: "queued".to_string(),
                    input_payload: json!({}),
                    output_payload: json!({}),
                    artifact_ids: Vec::new(),
                    approval_ids: Vec::new(),
                    tool_call_ids: Vec::new(),
                    claimed_by_worker: None,
                    lease_expires_at: None,
                    context_packet_id: None,
                    started_at: None,
                    completed_at: None,
                    scheduled_at: None,
                    created_at: now,
                    updated_at: now,
                })
                .await
                .expect("reserve workflow step key")
        }));
    }

    let mut created_count = 0;
    for caller in callers {
        if caller
            .await
            .expect("workflow step reservation task")
            .is_some()
        {
            created_count += 1;
        }
    }
    assert_eq!(created_count, 1);
    let stored = state
        .list_workflow_step_runs(workflow_run_id)
        .await
        .expect("list reserved workflow steps");
    assert_eq!(stored.len(), 1);
    assert_eq!(stored[0].step_key, "external-review");
}

