#[test]
fn agent_release_deployment_readiness_requires_controller_when_configured() {
    let generated_at = Utc::now();
    let missing = build_agent_release_deployment_readiness(&[], generated_at, true, false);
    assert_eq!(missing.status, "blocked");
    assert!(missing.production_blocked);
    assert!(missing.controller_required);
    assert!(!missing.controller_configured);
    assert!(missing.blocking_reasons.iter().any(|reason| {
        reason == "agent release deployment controller is required but not configured"
    }));

    let without_controller = build_agent_release_deployment_readiness(
        &[new_audit_log(
            None,
            "user",
            None,
            "agent.release_deployment_validation_run",
            "agent_release",
            None,
            json!({
                "status": "healthy",
                "release_count": 1,
                "pending_count": 0,
                "promoted_count": 1,
                "rejected_count": 0,
                "rolled_back_count": 0,
                "controller_required": true,
                "controller_configured": true,
                "controller_execution": {
                    "attempted": false,
                    "status": "skipped",
                    "reason": "controller_not_configured"
                }
            }),
        )],
        generated_at,
        true,
        true,
    );
    assert_eq!(without_controller.status, "blocked");
    assert!(without_controller.production_blocked);
    assert!(!without_controller.latest_controller_validated);

    let ready = build_agent_release_deployment_readiness(
        &[new_audit_log(
            None,
            "user",
            None,
            "agent.release_deployment_validation_run",
            "agent_release",
            None,
            json!({
                "status": "healthy",
                "release_count": 1,
                "pending_count": 0,
                "promoted_count": 1,
                "rejected_count": 0,
                "rolled_back_count": 0,
                "controller_required": true,
                "controller_configured": true,
                "controller_execution": {
                    "attempted": true,
                    "status": "validated",
                    "deployment_id": "agent-release-deployment-1"
                }
            }),
        )],
        generated_at,
        true,
        true,
    );
    assert_eq!(ready.status, "ready");
    assert!(!ready.production_blocked);
    assert_eq!(ready.latest_controller_status.as_deref(), Some("validated"));
    assert!(ready.latest_controller_validated);
    assert!(ready.controller_evidence_fresh);
    assert_eq!(ready.latest_controller_age_hours, Some(0));
    assert_eq!(ready.controller_execution_count, 1);
    assert_eq!(ready.controller_failed_count, 0);

    let mut stale_controller_audit = new_audit_log(
        None,
        "user",
        None,
        "agent.release_deployment_validation_run",
        "agent_release",
        None,
        json!({
            "status": "healthy",
            "release_count": 1,
            "pending_count": 0,
            "promoted_count": 1,
            "rejected_count": 0,
            "rolled_back_count": 0,
            "controller_required": true,
            "controller_configured": true,
            "controller_execution": {
                "attempted": true,
                "status": "validated",
                "deployment_id": "agent-release-deployment-1"
            }
        }),
    );
    stale_controller_audit.created_at = generated_at - chrono::Duration::hours(25);
    let stale = build_agent_release_deployment_readiness(
        &[stale_controller_audit],
        generated_at,
        true,
        true,
    );
    assert_eq!(stale.status, "blocked");
    assert!(stale.production_blocked);
    assert_eq!(stale.latest_controller_status.as_deref(), Some("validated"));
    assert!(stale.latest_controller_validated);
    assert!(!stale.controller_evidence_fresh);
    assert_eq!(stale.latest_controller_age_hours, Some(25));
    assert!(
        stale
            .blocking_reasons
            .iter()
            .any(|reason| reason == "agent release deployment controller evidence is stale")
    );
}

