fn test_state_with_worker(execution_worker: Arc<dyn ExecutionWorker>) -> AppState {
    // Tests that need insecure dev auth explicitly opt in via the environment variable
    // rather than relying on cfg!(test) in the auth layer (which is a security risk if
    // test binaries are exposed). Tests that need auth OFF reset this via EnvVarGuard
    // before calling this function, so we only set it when it is not already configured.
    if std::env::var("MANDOFORGE_INSECURE_DEV_AUTH").is_err() {
        unsafe {
            std::env::set_var("MANDOFORGE_INSECURE_DEV_AUTH", "1");
        }
    }
    AppState {
        store: StoreBackend::Memory(Arc::new(RwLock::new(MemoryStore::default()))),
        execution_queue: ExecutionQueue::default(),
        execution_worker,
        authorizer: Arc::new(RoleBasedAuthorizer),
        observability_config: ObservabilityConfig {
            service_name: "mandoforge-api-test".to_string(),
            otlp_endpoint: None,
            collector_health_endpoint: None,
            sample_ratio: 1.0,
        },
        telemetry_exporter: Arc::new(ReservedTelemetryExporter),
        mcp_gateway_config: None,
        mcp_gateway_client: Arc::new(ReservedMcpGatewayClient),
        codex_app_server_config: None,
        codex_app_server_client: Arc::new(ReservedCodexAppServerClient),
        eval_judge_config: None,
        eval_judge_client: Arc::new(ReservedEvalJudgeClient),
        cost_alert_webhook_url: None,
        cost_alert_email_relay_url: None,
        cost_alert_smtp_config: None,
        approval_webhook_url: None,
        workspace_root: test_workspace_root(),
        tenant_id: Uuid::parse_str("00000000-0000-4000-8000-000000000001").expect("valid uuid"),
        tenant_runtime_mode: TenantRuntimeMode::SingleRuntimeTenant,
        policy: runtime_policy(PolicyConfig::default()),
    }
}

fn test_policy_body(http_allowed: bool) -> Value {
    let approval_required = if http_allowed {
        json!([
            {"tool": "shell.exec", "risk": "high"},
            {"tool": "codex.exec", "risk": "high"},
            {"tool": "file.write", "risk": "medium"}
        ])
    } else {
        json!([
            {"tool": "shell.exec", "risk": "high"},
            {"tool": "codex.exec", "risk": "high"},
            {"tool": "file.write", "risk": "medium"},
            {"tool": "http.request", "risk": "high"}
        ])
    };
    json!({
        "blocked_tools": ["secret.read"],
        "approval_required": approval_required,
        "allowed_tools": {
            "generic-orchestrator-agent": ["file.read", "file.write", "sql.get_schema", "sql.query", "shell.exec", "codex.exec", "approval.request", "artifact.create", "mcp.call", "http.request"]
        },
        "sql_policy": {
            "max_rows": 500,
            "blocked_keywords": ["INSERT", "UPDATE", "DELETE", "DROP"]
        }
    })
}

#[tokio::test]
async fn staged_policy_rollout_selects_candidate_by_session_bucket() {
    let state = test_state_with_worker(Arc::new(InlineExecutionWorker));
    let staged_policy = serde_json::from_value::<PolicyConfig>(json!({
            "blocked_tools": ["secret.read"],
            "approval_required": [
                {"tool": "shell.exec", "risk": "high"},
                {"tool": "codex.exec", "risk": "high"},
                {"tool": "file.write", "risk": "medium"}
            ],
            "allowed_tools": {
                "generic-orchestrator-agent": ["file.read", "file.write", "sql.get_schema", "sql.query", "shell.exec", "codex.exec", "approval.request", "artifact.create", "mcp.call", "http.request"]
            },
            "sql_policy": {
                "max_rows": 500,
                "blocked_keywords": ["INSERT", "UPDATE", "DELETE", "DROP"]
            }
        }))
        .expect("policy");
    state
        .activate_runtime_policy(Uuid::new_v4(), staged_policy, 1)
        .await;

    let candidate_session = Uuid::from_u128(0);
    let baseline_session = Uuid::from_u128(99);
    assert_eq!(
        state
            .policy_for_session(candidate_session)
            .await
            .evaluate_tool("http.request")
            .decision,
        "allowed"
    );
    assert_eq!(
        state
            .policy_for_session(baseline_session)
            .await
            .evaluate_tool("http.request")
            .decision,
        "requires_approval"
    );
}

#[tokio::test]
async fn principal_auth_fails_closed_without_dev_auth() {
    let _env_guard = env_lock().lock().expect("env lock");
    let _insecure_auth = EnvVarGuard::set("MANDOFORGE_INSECURE_DEV_AUTH", "0");
    let _dev_token = EnvVarGuard::remove("MANDOFORGE_DEV_ADMIN_TOKEN");
    let _tenant_trust = EnvVarGuard::remove("MANDOFORGE_TRUST_X_MANDOFORGE_TENANT_ID");
    let _subject_trust = EnvVarGuard::remove("MANDOFORGE_TRUST_X_MANDOFORGE_SUBJECT");
    let state = test_state_with_worker(Arc::new(InlineExecutionWorker));

    let missing_subject = principal_from_request(&state, &HeaderMap::new())
        .await
        .expect_err("missing subject should fail closed");
    assert_eq!(missing_subject.status, StatusCode::UNAUTHORIZED);

    let mut forged_roles = HeaderMap::new();
    forged_roles.insert("x-mandoforge-subject", "admin-1".parse().unwrap());
    forged_roles.insert("x-mandoforge-roles", "admin".parse().unwrap());
    let forged_error = principal_from_request(&state, &forged_roles)
        .await
        .expect_err("client-forged subject should be rejected");
    assert_eq!(forged_error.status, StatusCode::UNAUTHORIZED);

    let _subject_trust = EnvVarGuard::set("MANDOFORGE_TRUST_X_MANDOFORGE_SUBJECT", "1");
    let trusted_subject_forged_roles_error = principal_from_request(&state, &forged_roles)
        .await
        .expect_err("trusted subject ingress still rejects client-forged roles");
    assert_eq!(
        trusted_subject_forged_roles_error.status,
        StatusCode::FORBIDDEN
    );

    let mut trusted_subject = HeaderMap::new();
    trusted_subject.insert("x-mandoforge-subject", "admin-1".parse().unwrap());
    let trusted_subject_without_membership = principal_from_request(&state, &trusted_subject)
        .await
        .expect_err("trusted subject ingress still requires membership roles");
    assert_eq!(
        trusted_subject_without_membership.status,
        StatusCode::FORBIDDEN
    );
}

#[tokio::test]
async fn tenant_routed_header_requires_trusted_ingress() {
    let _env_guard = env_lock().lock().expect("env lock");
    let _insecure_auth = EnvVarGuard::set("MANDOFORGE_INSECURE_DEV_AUTH", "0");
    let tenant_trust = EnvVarGuard::remove("MANDOFORGE_TRUST_X_MANDOFORGE_TENANT_ID");
    let mut state = test_state_with_worker(Arc::new(InlineExecutionWorker));
    state.tenant_runtime_mode = TenantRuntimeMode::TenantRouted;
    let mut headers = HeaderMap::new();
    headers.insert(
        "x-mandoforge-tenant-id",
        Uuid::new_v4().to_string().parse().unwrap(),
    );

    let error = resolve_request_tenant_id(&state, &headers)
        .expect_err("untrusted tenant header should fail closed");
    assert_eq!(error.status, StatusCode::FORBIDDEN);

    drop(tenant_trust);
    let _tenant_trust = EnvVarGuard::set("MANDOFORGE_TRUST_X_MANDOFORGE_TENANT_ID", "1");
    assert!(resolve_request_tenant_id(&state, &headers).is_ok());
}

#[tokio::test]
async fn policy_rollout_can_rollback_and_run_due_activation() {
    let app = test_app().await;

    let baseline_revision: PolicyRevision = request_json(
        app.clone(),
        Request::builder()
            .method("POST")
            .uri("/api/policy/revisions")
            .header("content-type", "application/json")
            .header("x-mandoforge-subject", "admin-1")
            .header("x-mandoforge-roles", "admin")
            .body(Body::from(
                json!({
                    "name": "rollback-baseline-policy",
                    "body": test_policy_body(false)
                })
                .to_string(),
            ))
            .expect("valid request"),
    )
    .await;
    let _: PolicyRevisionGate = request_json(
        app.clone(),
        Request::builder()
            .method("POST")
            .uri(format!(
                "/api/policy/revisions/{}/gate",
                baseline_revision.id
            ))
            .header("x-mandoforge-subject", "admin-1")
            .header("x-mandoforge-roles", "admin")
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    let _: PolicyRevision = request_json(
        app.clone(),
        Request::builder()
            .method("POST")
            .uri(format!(
                "/api/policy/revisions/{}/activate",
                baseline_revision.id
            ))
            .header("x-mandoforge-subject", "admin-1")
            .header("x-mandoforge-roles", "admin")
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;

    let permissive_revision: PolicyRevision = request_json(
        app.clone(),
        Request::builder()
            .method("POST")
            .uri("/api/policy/revisions")
            .header("content-type", "application/json")
            .header("x-mandoforge-subject", "admin-1")
            .header("x-mandoforge-roles", "admin")
            .body(Body::from(
                json!({
                    "name": "rollback-permissive-policy",
                    "body": test_policy_body(true)
                })
                .to_string(),
            ))
            .expect("valid request"),
    )
    .await;
    let _: PolicyRevisionGate = request_json(
        app.clone(),
        Request::builder()
            .method("POST")
            .uri(format!(
                "/api/policy/revisions/{}/gate",
                permissive_revision.id
            ))
            .header("x-mandoforge-subject", "admin-1")
            .header("x-mandoforge-roles", "admin")
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    let _: PolicyRevision = request_json(
        app.clone(),
        Request::builder()
            .method("POST")
            .uri(format!(
                "/api/policy/revisions/{}/activate",
                permissive_revision.id
            ))
            .header("x-mandoforge-subject", "admin-1")
            .header("x-mandoforge-roles", "admin")
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;

    let allowed_http: Value = request_json(
        app.clone(),
        Request::builder()
            .method("POST")
            .uri("/api/policy/simulate")
            .header("content-type", "application/json")
            .header("x-mandoforge-subject", "admin-1")
            .header("x-mandoforge-roles", "admin")
            .body(Body::from(json!({"tool_name": "http.request"}).to_string()))
            .expect("valid request"),
    )
    .await;
    assert_eq!(allowed_http["decision"], "allowed");

    let rollback: PolicyRollbackResult = request_json(
        app.clone(),
        Request::builder()
            .method("POST")
            .uri("/api/policy/rollout/rollback")
            .header("x-mandoforge-subject", "admin-1")
            .header("x-mandoforge-roles", "admin")
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    assert_eq!(
        rollback.rolled_back_from_revision_id,
        permissive_revision.id
    );
    assert_eq!(rollback.active_revision_id, baseline_revision.id);
    assert_eq!(rollback.active_revision.status, "active");

    let rollback_http: Value = request_json(
        app.clone(),
        Request::builder()
            .method("POST")
            .uri("/api/policy/simulate")
            .header("content-type", "application/json")
            .header("x-mandoforge-subject", "admin-1")
            .header("x-mandoforge-roles", "admin")
            .body(Body::from(json!({"tool_name": "http.request"}).to_string()))
            .expect("valid request"),
    )
    .await;
    assert_eq!(rollback_http["decision"], "requires_approval");

    let scheduled_revision: PolicyRevision = request_json(
        app.clone(),
        Request::builder()
            .method("POST")
            .uri("/api/policy/revisions")
            .header("content-type", "application/json")
            .header("x-mandoforge-subject", "admin-1")
            .header("x-mandoforge-roles", "admin")
            .body(Body::from(
                json!({
                    "name": "scheduled-due-policy",
                    "body": test_policy_body(true)
                })
                .to_string(),
            ))
            .expect("valid request"),
    )
    .await;
    let activate_after = (Utc::now() - chrono::Duration::minutes(1)).to_rfc3339();
    let activate_before = (Utc::now() + chrono::Duration::hours(1)).to_rfc3339();
    let scheduled_gate: PolicyRevisionGate = request_json(
        app.clone(),
        Request::builder()
            .method("POST")
            .uri(format!(
                "/api/policy/revisions/{}/gate",
                scheduled_revision.id
            ))
            .header("content-type", "application/json")
            .header("x-mandoforge-subject", "admin-1")
            .header("x-mandoforge-roles", "admin")
            .body(Body::from(
                json!({
                    "activate_after": activate_after,
                    "activate_before": activate_before
                })
                .to_string(),
            ))
            .expect("valid request"),
    )
    .await;
    assert_eq!(scheduled_gate.status, "passed");

    let scheduled_run: PolicyScheduledRolloutRun = request_json(
        app.clone(),
        Request::builder()
            .method("POST")
            .uri("/api/policy/rollout/run-due")
            .header("x-mandoforge-subject", "admin-1")
            .header("x-mandoforge-roles", "admin")
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    assert_eq!(scheduled_run.status, "activated");
    assert_eq!(
        scheduled_run.activated_revision_id,
        Some(scheduled_revision.id)
    );
    assert_eq!(
        scheduled_run.scanned_count,
        scheduled_run.scanned_revisions.len()
    );
    assert!(scheduled_run.scanned_revisions.iter().any(|revision| {
        revision.revision_id == scheduled_revision.id
            && revision.status == "activated"
            && revision.policy_id == "scheduled-due-policy"
            && revision.audit_id != Uuid::nil()
    }));

    let scheduled_http: Value = request_json(
        app.clone(),
        Request::builder()
            .method("POST")
            .uri("/api/policy/simulate")
            .header("content-type", "application/json")
            .header("x-mandoforge-subject", "admin-1")
            .header("x-mandoforge-roles", "admin")
            .body(Body::from(json!({"tool_name": "http.request"}).to_string()))
            .expect("valid request"),
    )
    .await;
    assert_eq!(scheduled_http["decision"], "allowed");

    let audit_logs: Vec<AuditLog> = request_json(
        app,
        Request::builder()
            .uri("/api/audit-logs")
            .header("x-mandoforge-subject", "admin-1")
            .header("x-mandoforge-roles", "admin")
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    assert!(
        audit_logs
            .iter()
            .any(|log| log.action == "policy.rollback_completed")
    );
    assert!(
        audit_logs
            .iter()
            .any(|log| log.action == "policy.rollout_due_run")
    );
}

