#[tokio::test]
async fn session_loop_job_enqueue_preserves_queued_job_while_another_job_runs() {
    let state = test_state_with_worker(Arc::new(InlineExecutionWorker));
    state.seed_demo_agent().await.expect("seed demo agent");
    let agent = state
        .list_agents()
        .await
        .expect("list agents")
        .into_iter()
        .next()
        .expect("seeded agent");
    let session = state
        .create_session(CreateSession {
            agent_id: agent.id,
            environment_id: None,
            title: "session loop running plus queued".to_string(),
            message: None,
        })
        .await
        .expect("create session");

    let first_event = state
        .append_event(
            "user",
            None,
            session.id,
            "user.message",
            json!({"message": "first event"}),
        )
        .await
        .expect("append first event");
    let first = state
        .enqueue_session_loop_job(session.id, Some(first_event.id), "user.message")
        .await
        .expect("enqueue first job");
    assert_eq!(first.pending_event_seq_start, Some(first_event.seq));
    assert_eq!(first.pending_event_seq_end, Some(first_event.seq));
    let running = state
        .start_session_loop_job(first.id, "loop-worker-a")
        .await
        .expect("start first job");
    assert_eq!(running.status, SessionLoopJobStatus::Running);

    let second_event = state
        .append_event(
            "user",
            None,
            session.id,
            "user.custom_tool_result",
            json!({"custom_tool_call_id": "custom-while-running", "result": {"status": "ok"}}),
        )
        .await
        .expect("append second event");
    let second = state
        .enqueue_session_loop_job(session.id, Some(second_event.id), "user.custom_tool_result")
        .await
        .expect("enqueue second job while first is running");
    assert_ne!(second.id, running.id);
    assert_eq!(second.status, SessionLoopJobStatus::Queued);
    assert_eq!(second.reason, "user.custom_tool_result");
    assert_eq!(second.trigger_event_id, Some(second_event.id));
    assert_eq!(second.pending_event_seq_start, Some(second_event.seq));
    assert_eq!(second.pending_event_seq_end, Some(second_event.seq));
    assert_eq!(second.processed_event_seq, Some(first_event.seq));

    let jobs = state
        .list_session_loop_jobs()
        .await
        .expect("list session loop jobs");
    let session_jobs: Vec<_> = jobs
        .into_iter()
        .filter(|job| job.session_id == session.id)
        .collect();
    assert_eq!(session_jobs.len(), 2);
    assert_eq!(
        session_jobs
            .iter()
            .filter(|job| job.status == SessionLoopJobStatus::Running)
            .count(),
        1
    );
    assert_eq!(
        session_jobs
            .iter()
            .filter(|job| job.status == SessionLoopJobStatus::Queued)
            .count(),
        1
    );
    let blocked_start = state
        .start_session_loop_job(second.id, "loop-worker-b")
        .await
        .expect_err("queued job should not start while another job is running");
    assert_eq!(blocked_start.status, StatusCode::NOT_FOUND);

    let stale_complete = state
        .complete_session_loop_job(running.id, "loop-worker-b")
        .await
        .expect_err("stale worker cannot complete another worker's loop job");
    assert_eq!(stale_complete.status, StatusCode::NOT_FOUND);
    let completed = state
        .complete_session_loop_job(running.id, "loop-worker-a")
        .await
        .expect("owning worker can complete loop job");
    assert_eq!(completed.status, SessionLoopJobStatus::Completed);
    assert_eq!(completed.processed_event_seq, Some(first_event.seq));
}

#[tokio::test]
async fn terminal_session_loop_job_is_discarded_without_failing_session() {
    let app = test_app().await;
    let agents: Vec<Agent> = request_json(
        app.clone(),
        Request::builder()
            .uri("/api/agents")
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    let agent = agents
        .iter()
        .find(|agent| agent.name == "Generic Orchestrator Agent")
        .expect("seeded generic orchestrator agent");

    let session: Session = request_json(
        app.clone(),
        json_request(
            "POST",
            "/api/sessions",
            json!({
                "agent_id": agent.id,
                "title": "terminal session stale loop job"
            }),
        ),
    )
    .await;
    let events: Vec<SessionEvent> = request_json(
        app.clone(),
        json_request(
            "POST",
            &format!("/api/sessions/{}/events", session.id),
            json!({
                "events": [{
                    "type": "user.message",
                    "payload": {"message": "This job will be stale before it runs."}
                }]
            }),
        ),
    )
    .await;
    assert_eq!(events.len(), 1);
    let queued = session_loop_jobs_for_session(app.clone(), session.id).await;
    assert_eq!(queued.len(), 1);
    assert_eq!(queued[0].status, SessionLoopJobStatus::Queued);

    let interrupted: Vec<SessionEvent> = request_json(
        app.clone(),
        json_request(
            "POST",
            &format!("/api/sessions/{}/events", session.id),
            json!({
                "events": [{
                    "type": "user.interrupt",
                    "payload": {"reason": "operator stop"}
                }]
            }),
        ),
    )
    .await;
    assert_eq!(interrupted.len(), 1);
    let terminal_before: Session = request_json(
        app.clone(),
        Request::builder()
            .uri(format!("/api/sessions/{}", session.id))
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    assert!(matches!(terminal_before.status, SessionStatus::Terminated));

    let skipped = run_next_session_loop_job(app.clone(), session.id, "stale-loop-worker").await;
    assert_eq!(skipped.status, SessionLoopJobStatus::Failed);
    assert_eq!(
        skipped.last_error.as_deref(),
        Some("session is terminal and cannot run session loop work")
    );

    let terminal_after: Session = request_json(
        app.clone(),
        Request::builder()
            .uri(format!("/api/sessions/{}", session.id))
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    assert!(matches!(terminal_after.status, SessionStatus::Terminated));
    let events_after: Vec<SessionEvent> = request_json(
        app,
        Request::builder()
            .uri(format!("/api/sessions/{}/events", session.id))
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    assert!(events_after.iter().any(|event| {
        event.event_type == "session.loop.skipped"
            && event.payload["session_loop_job_id"] == json!(queued[0].id)
    }));
}

#[tokio::test]
async fn terminal_session_rejects_new_event_driven_loop_work() {
    let app = test_app().await;
    let agents: Vec<Agent> = request_json(
        app.clone(),
        Request::builder()
            .uri("/api/agents")
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    let agent = agents
        .iter()
        .find(|agent| agent.name == "Generic Orchestrator Agent")
        .expect("seeded generic orchestrator agent");

    let session: Session = request_json(
        app.clone(),
        json_request(
            "POST",
            "/api/sessions",
            json!({
                "agent_id": agent.id,
                "title": "terminal session rejects fresh event work"
            }),
        ),
    )
    .await;
    let interrupted: Vec<SessionEvent> = request_json(
        app.clone(),
        json_request(
            "POST",
            &format!("/api/sessions/{}/events", session.id),
            json!({
                "events": [{
                    "type": "user.interrupt",
                    "payload": {"reason": "operator stop before new event"}
                }]
            }),
        ),
    )
    .await;
    assert_eq!(interrupted.len(), 1);
    let terminal: Session = request_json(
        app.clone(),
        Request::builder()
            .uri(format!("/api/sessions/{}", session.id))
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    assert!(matches!(terminal.status, SessionStatus::Terminated));

    let (status, rejected) = request_value(
        app.clone(),
        json_request(
            "POST",
            &format!("/api/sessions/{}/events", session.id),
            json!({
                "events": [{
                    "type": "user.message",
                    "payload": {"message": "This must not restart a failed session."}
                }]
            }),
        ),
    )
    .await;
    assert_eq!(status, StatusCode::BAD_REQUEST);
    assert!(
        rejected["error"]
            .as_str()
            .unwrap_or_default()
            .contains("session is terminal and cannot enqueue session loop work")
    );
    let jobs = session_loop_jobs_for_session(app.clone(), session.id).await;
    assert!(
        jobs.is_empty(),
        "terminal event append must not create loop work: {jobs:?}"
    );
}

