#[tokio::test]
async fn loads_stage1_policy_from_yaml() {
    let policy_path = format!(
        "{}/../../config/policy.stage1.yaml",
        env!("CARGO_MANIFEST_DIR")
    );
    let policy = load_policy_config(&policy_path)
        .await
        .expect("load stage 1 policy");

    let shell = policy.evaluate_tool("shell.exec");
    assert_eq!(shell.decision, "requires_approval");
    assert_eq!(shell.risk_level, "high");

    let pwd = policy.evaluate_tool_with_args("shell.exec", &json!({"command": "pwd"}));
    assert_eq!(pwd.decision, "requires_approval");
    assert_eq!(pwd.risk_level, "high");

    let destructive_shell =
        policy.evaluate_tool_with_args("shell.exec", &json!({"command": "rm -rf /tmp/x"}));
    assert_eq!(destructive_shell.decision, "requires_approval");
    assert_eq!(destructive_shell.risk_level, "high");

    let secret = policy.evaluate_tool("secret.read");
    assert_eq!(secret.decision, "denied");

    let file_read = policy.evaluate_tool("file.read");
    assert_eq!(file_read.decision, "allowed");

    let schema = policy.evaluate_tool("sql.get_schema");
    assert_eq!(schema.decision, "allowed");
}

#[tokio::test]
async fn manual_tool_execution_uses_policy_for_approval_and_denial() {
    let app = test_app().await;
    let agents: Vec<Agent> = request_json(
        app.clone(),
        Request::builder()
            .uri("/api/agents")
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    let agent = agents.first().expect("seeded agent");
    let session: Session = request_json(
        app.clone(),
        json_request(
            "POST",
            "/api/sessions",
            json!({"agent_id": agent.id, "title": "manual tools"}),
        ),
    )
    .await;

    let approval_result: Value = request_json(
            app.clone(),
            json_request(
                "POST",
                "/api/tools/shell.exec/execute",
                json!({"session_id": session.id, "args": {"command": "rm -rf /tmp/mandoforge-policy-test"}}),
            ),
        )
        .await;
    assert_eq!(approval_result["status"], "approval_required");
    assert!(approval_result.get("approval_id").is_some());

    let approvals: Vec<Approval> = request_json(
        app.clone(),
        Request::builder()
            .uri("/api/approvals")
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    assert!(approvals.iter().any(|approval| {
        approval.session_id == session.id
            && approval.action == "shell.exec"
            && approval.status == "pending"
    }));

    let waiting: Session = request_json(
        app.clone(),
        Request::builder()
            .uri(format!("/api/sessions/{}", session.id))
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    assert!(matches!(waiting.status, SessionStatus::RequiresAction));

    let (status, error) = request_value(
        app.clone(),
        json_request(
            "POST",
            "/api/tools/secret.read/execute",
            json!({"session_id": session.id, "args": {"name": "api_key"}}),
        ),
    )
    .await;
    assert_eq!(status, StatusCode::FORBIDDEN);
    assert!(
        error["error"]
            .as_str()
            .unwrap_or_default()
            .contains("blocked")
    );

    let events: Vec<SessionEvent> = request_json(
        app.clone(),
        Request::builder()
            .uri(format!("/api/sessions/{}/events", session.id))
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    assert!(
        events
            .iter()
            .any(|event| event.event_type == "policy.denied")
    );
    assert!(
        events
            .iter()
            .any(|event| event.event_type == "approval.requested")
    );

    let tool_calls: Vec<ToolCall> = request_json(
        app,
        Request::builder()
            .uri(format!("/api/sessions/{}/tool-calls", session.id))
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    assert!(tool_calls.iter().any(|call| {
        call.tool_name == "shell.exec"
            && call.status == "waiting_approval"
            && call.policy_decision["decision"] == "requires_approval"
    }));
    assert!(tool_calls.iter().any(|call| {
        call.tool_name == "secret.read"
            && call.status == "denied"
            && call.policy_decision["decision"] == "denied"
    }));
}

#[tokio::test]
async fn manual_allowed_tool_result_resumes_session_loop() {
    let app = test_app().await;
    let agents: Vec<Agent> = request_json(
        app.clone(),
        Request::builder()
            .uri("/api/agents")
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    let agent = agents.first().expect("seeded agent");
    let session: Session = request_json(
        app.clone(),
        json_request(
            "POST",
            "/api/sessions",
            json!({"agent_id": agent.id, "title": "manual allowed tool result"}),
        ),
    )
    .await;

    let read_result: Value = request_json(
        app.clone(),
        json_request(
            "POST",
            "/api/tools/file.read/execute",
            json!({"session_id": session.id, "args": {"path": "README.md"}}),
        ),
    )
    .await;
    assert!(read_result.get("files").is_some());

    let events: Vec<SessionEvent> = request_json(
        app.clone(),
        Request::builder()
            .uri(format!("/api/sessions/{}/events", session.id))
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    let tool_result_event = events
        .iter()
        .find(|event| event.event_type == "tool.result")
        .expect("manual allowed tool should record a durable tool.result event");

    let queued_jobs = session_loop_jobs_for_session(app.clone(), session.id).await;
    assert!(
        queued_jobs.iter().any(|job| {
            job.status == SessionLoopJobStatus::Queued
                && job.reason == "tool.result"
                && job.trigger_event_id == Some(tool_result_event.id)
        }),
        "manual tool result should resume through session-loop queue: {queued_jobs:?}"
    );

    let completed =
        run_next_session_loop_job(app.clone(), session.id, "manual-tool-result-worker").await;
    assert_eq!(completed.status, SessionLoopJobStatus::Completed);

    let events_after_resume: Vec<SessionEvent> = request_json(
        app,
        Request::builder()
            .uri(format!("/api/sessions/{}/events", session.id))
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    assert!(events_after_resume.iter().any(|event| {
        event.event_type == "llm.request"
            && event.payload["context"]["manual_tool_result_count"] == json!(1)
    }));
    assert!(events_after_resume.iter().any(|event| {
        event.event_type == "agent.final"
            && event
                .payload
                .get("message")
                .and_then(Value::as_str)
                .is_some_and(|message| message.contains("Manual tool result"))
    }));
}

#[tokio::test]
async fn high_risk_tools_fail_closed_on_stale_or_untrusted_semantic_context() {
    let app = test_app().await;
    let source: SemanticSource = request_json(
        app.clone(),
        json_request_with_headers(
            "POST",
            "/api/semantic-sources",
            json!({
                "source_type": "repo_doc",
                "source_uri": "repo://docs/legacy-runbook.md",
                "display_name": "Legacy Runbook",
                "freshness": {"state": "stale"}
            }),
            &[
                ("x-mandoforge-subject", "admin-1"),
                ("x-mandoforge-roles", "admin"),
            ],
        ),
    )
    .await;
    let stale_object: SemanticObject = request_json(
        app.clone(),
        json_request_with_headers(
            "POST",
            "/api/semantic-objects",
            json!({
                "source_id": source.id,
                "object_type": "runbook",
                "object_key": "runbook:semantic-gate:stale",
                "title": "Stale deployment runbook",
                "summary": "This runbook matches the agent scope but is stale and unverified.",
                "content": {"step": "legacy shell execution"},
                "semantic_scopes": {
                    "project_scope": "mandoforge",
                    "repo_scope": "mandoforge",
                    "service_scope": "mandoforge-api",
                    "workflow_scope": "semantic-gate",
                    "policy_scope": "approval-required",
                    "memory_scope": "engineering"
                },
                "trust_level": "unverified",
                "freshness": "stale"
            }),
            &[
                ("x-mandoforge-subject", "admin-1"),
                ("x-mandoforge-roles", "admin"),
            ],
        ),
    )
    .await;
    let agent: Agent = request_json(
        app.clone(),
        json_request_with_headers(
            "POST",
            "/api/agents",
            json!({
                "name": "Semantic Gate Specialist",
                "kind": "specialist",
                "agent_role": "specialist",
                "provider": "openai-compatible",
                "model": "gpt-5.5-mini",
                "system_prompt": "Execute only with trusted semantic context.",
                "tools": ["file.read", "shell.exec"],
                "semantic_scopes": {
                    "project_scope": "mandoforge",
                    "repo_scope": "mandoforge",
                    "service_scope": "mandoforge-api",
                    "workflow_scope": "semantic-gate",
                    "policy_scope": "approval-required",
                    "memory_scope": "engineering"
                },
                "release_state": "active"
            }),
            &[
                ("x-mandoforge-subject", "admin-1"),
                ("x-mandoforge-roles", "admin"),
            ],
        ),
    )
    .await;
    let session: Session = request_json(
        app.clone(),
        json_request_with_headers(
            "POST",
            "/api/sessions",
            json!({
                "agent_id": agent.id,
                "title": "semantic context gate",
                "message": "Run a high-risk command only if context is trusted."
            }),
            &[
                ("x-mandoforge-subject", "admin-1"),
                ("x-mandoforge-roles", "admin"),
            ],
        ),
    )
    .await;

    let low_risk_result: Value = request_json(
        app.clone(),
        json_request(
            "POST",
            "/api/tools/file.read/execute",
            json!({"session_id": session.id, "args": {"path": "README.md"}}),
        ),
    )
    .await;
    assert!(low_risk_result.get("files").is_some());

    let (status, error) = request_value(
        app.clone(),
        json_request(
            "POST",
            "/api/tools/shell.exec/execute",
            json!({"session_id": session.id, "args": {"command": "pwd"}}),
        ),
    )
    .await;
    assert_eq!(status, StatusCode::FORBIDDEN);
    assert!(
        error["error"]
            .as_str()
            .unwrap_or_default()
            .contains("semantic context gate")
    );

    let approvals: Vec<Approval> = request_json(
        app.clone(),
        Request::builder()
            .uri("/api/approvals")
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    assert!(!approvals.iter().any(|approval| {
        approval.session_id == session.id
            && approval.action == "shell.exec"
            && approval.status == "pending"
    }));

    let events: Vec<SessionEvent> = request_json(
        app.clone(),
        Request::builder()
            .uri(format!("/api/sessions/{}/events", session.id))
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    assert!(events.iter().any(|event| {
        event.event_type == "semantic_context.gate_failed"
            && event.payload["content"]["semantic_context_gate"]["blockers"][0]["id"]
                == json!(stale_object.id)
    }));

    let audit_logs: Vec<AuditLog> = request_json(
        app.clone(),
        Request::builder()
            .uri("/api/audit-logs")
            .header("x-mandoforge-subject", "admin-1")
            .header("x-mandoforge-roles", "admin")
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    assert!(audit_logs.iter().any(|log| {
        log.action == "semantic_context.gate_failed"
            && log.details["semantic_context_gate"]["blocked_object_count"] == json!(1)
    }));

    let tool_calls: Vec<ToolCall> = request_json(
        app,
        Request::builder()
            .uri(format!("/api/sessions/{}/tool-calls", session.id))
            .body(Body::empty())
            .expect("valid request"),
    )
    .await;
    let shell_call = tool_calls
        .iter()
        .find(|call| call.tool_name == "shell.exec")
        .expect("shell call recorded");
    assert_eq!(shell_call.status, "denied");
    assert_eq!(
        shell_call.policy_decision["semantic_context_gate"]["status"],
        "blocked"
    );
    assert_eq!(
        shell_call.policy_decision["semantic_context_gate"]["boundary"],
        "agent_semantic_scope"
    );
    assert_eq!(
        shell_call.policy_decision["semantic_context_gate"]["blockers"][0]["reasons"],
        json!(["freshness_not_current", "trust_unverified"])
    );
    assert!(tool_calls.iter().any(|call| {
        call.tool_name == "file.read"
            && call.status == "completed"
            && call.policy_decision.get("semantic_context_gate").is_none()
    }));
}

